def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted = ord(char) + shift
            if shifted > ord('z'):
                shifted -= 26
            elif shifted < ord('a'):
                shifted += 26
            result.append(chr(shifted))
        elif 'A' <= char <= 'Z':
            shifted = ord(char) + shift
            if shifted > ord('Z'):
                shifted -= 26
            elif shifted < ord('A'):
                shifted += 26
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)
